import i18n from "../i18n";
import { inTauri, loadPlan, type Plan, type PlanContract } from "./ipc";
import type { ModelRef } from "./models";
import type { ChatMessage, Conversation, FileChange, ToolPart } from "../stores/chat";
import { useExecution } from "../stores/execution";

export interface ModelHandoffData {
  status: "generating" | "ready" | "sent";
  /** "model" when generated by the outgoing model; "tokage_local" when extracted by Tokage. */
  source: "model" | "tokage_local";
  /** Full Markdown handoff document. */
  document: string;
  /** Optional fallback reason when Tokage extracted the handoff locally. */
  fallbackReason?: string;
  /** Active turnId while the outgoing model is generating the handoff document. */
  reportTurnId?: string;
}

export interface ModelSwitchInfo {
  kind: "direct" | "smart";
  fromRef: ModelRef;
  fromModelName?: string;
  toRef: ModelRef;
  toModelName?: string;
  handoff?: ModelHandoffData;
}

export interface SessionHandoffSnapshot {
  sessionId: string;
  cwd: string | null;
  fromRef: ModelRef;
  fromModelName: string;
  toRef: ModelRef;
  toModelName: string;
  initialGoal: string;
  followUpRequests: string[];
  planGoal: string | null;
  planContracts: PlanContract[];
  planTasksSummary: string[];
  extractedApisAndContracts: string[];
  fileChanges: {
    path: string;
    change: FileChange["change"];
    additions: number;
    deletions: number;
    diffExcerpt: string | null;
  }[];
  recentTools: {
    tool: string;
    title: string;
    ok: boolean | null;
    outputExcerpt: string | null;
  }[];
  recentAssistantOutputs: string[];
  pendingErrors: string[];
}

const clip = (text: string, maxChars: number): string => {
  const chars = Array.from(text.trim());
  if (chars.length <= maxChars) return chars.join("");
  return `${chars.slice(0, maxChars).join("")}…`;
};

/**
 * Returns the model that ran the last real assistant turn in this conversation,
 * or null if the conversation has not had any real model turns yet.
 */
export function getActiveSessionModelRef(
  conv: Conversation | undefined,
): { ref: ModelRef; modelName?: string } | null {
  if (!conv) return null;
  for (let i = conv.messages.length - 1; i >= 0; i--) {
    const m = conv.messages[i];
    if (m.origin === "tokage" || m.modelSwitch || m.contextReport) continue;
    if (m.role === "assistant" && (m.ref || (m.provider && m.model))) {
      const ref: ModelRef = m.ref ?? { provider: m.provider!, model: m.model! };
      return { ref, modelName: m.modelName ?? m.model };
    }
  }
  const hasRealUserMessage = conv.messages.some((m) => m.origin !== "tokage" && m.role === "user");
  if (hasRealUserMessage && conv.thread?.ref) {
    return { ref: conv.thread.ref, modelName: conv.thread.ref.model };
  }
  if (hasRealUserMessage && conv.lockedModel) {
    return { ref: conv.lockedModel, modelName: conv.lockedModel.model };
  }
  return null;
}

/**
 * Finds the latest `modelSwitch` message if no real user/assistant turn has happened after it.
 */
export function getUnsentModelSwitchMessage(conv: Conversation | undefined): ChatMessage | null {
  if (!conv) return null;
  for (let i = conv.messages.length - 1; i >= 0; i--) {
    const m = conv.messages[i];
    if (m.modelSwitch) return m;
    if (m.origin !== "tokage" && !m.contextReport) return null;
  }
  return null;
}

export function hasUnsentSmartHandoff(conv: Conversation | undefined): boolean {
  const msg = getUnsentModelSwitchMessage(conv);
  if (!msg?.modelSwitch || msg.modelSwitch.kind !== "smart") return false;
  const status = msg.modelSwitch.handoff?.status;
  return status === "generating" || status === "ready";
}

export function isSmartHandoffGenerating(conv: Conversation | undefined): boolean {
  const msg = getUnsentModelSwitchMessage(conv);
  return msg?.modelSwitch?.kind === "smart" && msg.modelSwitch.handoff?.status === "generating";
}

export function getReadySmartHandoffMessage(conv: Conversation | undefined): ChatMessage | null {
  const msg = getUnsentModelSwitchMessage(conv);
  if (msg?.modelSwitch?.kind === "smart" && msg.modelSwitch.handoff?.status === "ready") {
    return msg;
  }
  return null;
}

/**
 * Extracts API signatures, type/interface definitions, structs, IPC commands, and contracts
 * mentioned in assistant messages or file diffs.
 */
export function extractApiAndContractSnippets(messages: ChatMessage[], diffs: (string | null | undefined)[]): string[] {
  const results: string[] = [];
  const seen = new Set<string>();
  const add = (snippet: string) => {
    const normalized = snippet.trim();
    if (!normalized || seen.has(normalized)) return;
    seen.add(normalized);
    results.push(clip(normalized, 600));
  };

  const signatureRegex =
    /^(?:\s*(?:export\s+)?(?:async\s+)?(?:interface|type|function|class|const|enum)\s+[A-Za-z0-9_]+[^\n]*|\s*#\[tauri::command[^\]]*\]|\s*pub\s+(?:async\s+)?(?:fn|struct|enum|trait|type)\s+[A-Za-z0-9_]+[^\n]*)/gm;

  for (const m of messages) {
    if (m.origin === "tokage" || m.modelSwitch || m.contextReport || !m.text) continue;
    // Extract fenced code blocks or signature lines
    const matches = m.text.match(signatureRegex);
    if (matches) {
      for (const line of matches.slice(-12)) {
        add(line);
      }
    }
  }

  for (const diff of diffs) {
    if (!diff) continue;
    const addedLines = diff
      .split("\n")
      .filter((l) => l.startsWith("+") && !l.startsWith("+++"))
      .map((l) => l.slice(1));
    const joined = addedLines.join("\n");
    const matches = joined.match(signatureRegex);
    if (matches) {
      for (const line of matches.slice(-16)) {
        add(line);
      }
    }
  }

  return results.slice(-20);
}

/**
 * Collects a comprehensive deterministic snapshot of the current session's goals,
 * contracts, APIs, file modifications, tool runs, and pending errors.
 */
export async function collectSessionHandoffSnapshot(args: {
  conv: Conversation;
  sessionId: string;
  cwd: string | null;
  fromRef: ModelRef;
  fromModelName?: string;
  toRef: ModelRef;
  toModelName?: string;
}): Promise<SessionHandoffSnapshot> {
  const { conv, sessionId, cwd, fromRef, fromModelName, toRef, toModelName } = args;
  const realMessages = conv.messages.filter((m) => m.origin !== "tokage" && !m.modelSwitch && !m.contextReport);
  const userMessages = realMessages.filter((m) => m.role === "user" && m.text.trim()).map((m) => m.text.trim());
  const initialGoal = userMessages[0] ?? "";
  const followUpRequests = userMessages.slice(1).slice(-8).map((u) => clip(u, 600));

  let loadedPlan: Plan | null = null;
  if (cwd && inTauri) {
    const hasSavedPlan = realMessages.some((m) => m.plan);
    if (hasSavedPlan) {
      try {
        loadedPlan = await loadPlan(cwd, sessionId);
      } catch {
        loadedPlan = null;
      }
    }
  }

  const pipeline = useExecution.getState().pipelines[sessionId];
  const planGoal = loadedPlan?.spec?.goal || null;
  const planContracts: PlanContract[] = loadedPlan?.contracts ?? pipeline?.contracts ?? [];
  const planTasks = loadedPlan?.tasks ?? pipeline?.tasks ?? [];
  const planTasksSummary = planTasks.slice(0, 16).map((t) => {
    const state = pipeline?.taskStates?.[t.id] ?? "PLANNED";
    return `${t.id} (${state}): ${t.title}${t.goal ? ` — ${clip(t.goal, 160)}` : ""}`;
  });

  // Aggregate cumulative file changes across the session
  const fileMap = new Map<string, FileChange>();
  for (const m of realMessages) {
    for (const f of m.files ?? []) {
      const prev = fileMap.get(f.path);
      if (!prev) {
        fileMap.set(f.path, { ...f });
      } else {
        fileMap.set(f.path, {
          ...f,
          change: prev.change === "added" && f.change === "modified" ? "added" : f.change,
          diff: f.diff ?? prev.diff,
        });
      }
    }
  }
  const fileChanges = [...fileMap.values()].slice(-24).map((f) => ({
    path: f.path,
    change: f.change,
    additions: f.additions,
    deletions: f.deletions,
    diffExcerpt: f.diff ? clip(f.diff, 800) : null,
  }));

  // Extract API & contract signatures from messages and diffs
  const extractedApisAndContracts = extractApiAndContractSnippets(
    realMessages,
    [...fileMap.values()].map((f) => f.diff),
  );

  // Recent tool executions
  const allTools: ToolPart[] = [];
  for (const m of realMessages) {
    for (const p of m.parts ?? []) {
      if (p.type === "tool") allTools.push(p);
    }
  }
  const recentTools = allTools.slice(-12).map((p) => ({
    tool: p.tool,
    title: clip(p.title, 200),
    ok: p.ok,
    outputExcerpt: p.ok === false && p.output ? clip(p.output, 400) : null,
  }));

  // Recent assistant outputs
  const assistantMessages = realMessages.filter((m) => m.role === "assistant" && m.text.trim());
  const recentAssistantOutputs = assistantMessages.slice(-4).map((m) => clip(m.text, 1600));

  // Pending errors from recent turns or failed tools
  const pendingErrors: string[] = [];
  for (const m of realMessages.slice(-4)) {
    if (m.error) pendingErrors.push(clip(m.error, 500));
    for (const p of m.parts ?? []) {
      if (p.type === "tool" && p.ok === false) {
        pendingErrors.push(`[Tool ${p.tool}: ${clip(p.title, 120)}] ${p.output ? clip(p.output, 300) : "failed"}`);
      } else if (p.type === "warning") {
        pendingErrors.push(clip(p.message, 300));
      }
    }
  }

  return {
    sessionId,
    cwd,
    fromRef,
    fromModelName: fromModelName || fromRef.model,
    toRef,
    toModelName: toModelName || toRef.model,
    initialGoal: clip(initialGoal, 1500),
    followUpRequests,
    planGoal,
    planContracts,
    planTasksSummary,
    extractedApisAndContracts,
    fileChanges,
    recentTools,
    recentAssistantOutputs,
    pendingErrors: [...new Set(pendingErrors)].slice(-8),
  };
}

/**
 * Formats the deterministic session metadata section so both model-generated and
 * locally extracted handoff documents include verified contracts, APIs, and file changes.
 */
export function formatSnapshotContextSection(snapshot: SessionHandoffSnapshot): string {
  const lines: string[] = [];

  if (snapshot.planContracts.length > 0) {
    lines.push("### Verified Plan Contracts");
    for (const c of snapshot.planContracts.slice(0, 10)) {
      lines.push(`- **${c.id} (${c.title})**:\n\`\`\`\n${clip(c.content, 800)}\n\`\`\``);
    }
  }

  if (snapshot.extractedApisAndContracts.length > 0) {
    lines.push("### Key APIs, Signatures & Types in Session");
    lines.push("```");
    for (const sig of snapshot.extractedApisAndContracts) {
      lines.push(sig);
    }
    lines.push("```");
  }

  if (snapshot.fileChanges.length > 0) {
    lines.push("### Recorded File Changes");
    for (const f of snapshot.fileChanges) {
      lines.push(`- \`${f.path}\` (${f.change}, +${f.additions}/-${f.deletions})`);
    }
  }

  if (snapshot.planTasksSummary.length > 0) {
    lines.push("### Plan Tasks Status");
    for (const t of snapshot.planTasksSummary) {
      lines.push(`- ${t}`);
    }
  }

  if (snapshot.pendingErrors.length > 0) {
    lines.push("### Unresolved Errors / Warnings");
    for (const err of snapshot.pendingErrors) {
      lines.push(`- ${err}`);
    }
  }

  return lines.join("\n\n");
}

/**
 * Builds the prompt sent to the outgoing model to generate a comprehensive handoff document.
 */
export function buildModelHandoffGenerationPrompt(snapshot: SessionHandoffSnapshot): string {
  const verifiedFacts = formatSnapshotContextSection(snapshot);
  return [
    "You are handing off this active coding session to another model in a fresh context window.",
    "Do NOT edit files, run commands, or start new implementation work.",
    "Write a comprehensive, actionable Markdown Handoff Document in the user's language so the incoming model can immediately continue working without reading the raw chat history.",
    "",
    "Include all 5 sections below in order:",
    "## 1. Core Goal & User Requirements",
    "- Summarize the original objective, subsequent requirement refinements, and user constraints.",
    "## 2. Key Contracts, APIs & Architectural Invariants",
    "- Explicitly list all relevant function/method signatures, TypeScript/Rust types & interfaces, IPC/API contracts, store state shapes, and invariants that must be preserved.",
    "## 3. Completed Work & Code Changes",
    "- Detail each modified/added file, what was implemented, and how components interact.",
    "## 4. Current Verification State, Open Issues & Pitfalls",
    "- State what tests/builds were run, any unresolved errors, rejected approaches, or edge cases to watch out for.",
    "## 5. Immediate Next Steps for Incoming Model",
    "- Provide concrete, step-by-step instructions on what the incoming model should do next.",
    "",
    verifiedFacts ? `Reference session artifacts collected by Tokage:\n${verifiedFacts}` : "",
  ]
    .filter(Boolean)
    .join("\n");
}

/**
 * Combines the outgoing model's summary with Tokage's deterministic contract/API/file appendix.
 */
export function composeFinalModelHandoffDocument(
  modelOutput: string,
  snapshot: SessionHandoffSnapshot,
): string {
  const cleaned = modelOutput.trim();
  const appendix = formatSnapshotContextSection(snapshot);
  if (!appendix) return cleaned;
  return `${cleaned}\n\n---\n\n## Session Artifacts Appendix (Verified by Tokage)\n\n${appendix}`;
}

/**
 * Builds a complete handoff document locally when the outgoing model cannot generate one
 * (e.g. quota exhausted, network error, or user requested immediate local extraction).
 */
export function buildLocalHandoffDocument(snapshot: SessionHandoffSnapshot): string {
  const t = i18n.t.bind(i18n);
  const sections: string[] = [];

  sections.push(`# ${t("workspace.handoff.docTitle")} (${t("workspace.handoff.localSourceTag")})`);
  sections.push(
    `> ${t("workspace.handoff.localDocNotice", {
      from: snapshot.fromModelName,
      to: snapshot.toModelName,
    })}`,
  );

  // 1. Goals & Requirements
  const reqLines: string[] = [`## 1. ${t("workspace.handoff.secGoals")}`];
  reqLines.push(`- **${t("workspace.handoff.initialRequest")}**: ${snapshot.initialGoal || t("workspace.handoff.noneRecorded")}`);
  if (snapshot.planGoal) {
    reqLines.push(`- **${t("workspace.handoff.planGoal")}**: ${snapshot.planGoal}`);
  }
  if (snapshot.followUpRequests.length > 0) {
    reqLines.push(`- **${t("workspace.handoff.followUpRequests")}**:`);
    for (const req of snapshot.followUpRequests) {
      reqLines.push(`  - ${req}`);
    }
  }
  sections.push(reqLines.join("\n"));

  // 2. Contracts & APIs
  const apiLines: string[] = [`## 2. ${t("workspace.handoff.secContracts")}`];
  if (snapshot.planContracts.length > 0) {
    for (const c of snapshot.planContracts) {
      apiLines.push(`### ${c.id}: ${c.title}\n\`\`\`\n${clip(c.content, 1000)}\n\`\`\``);
    }
  }
  if (snapshot.extractedApisAndContracts.length > 0) {
    apiLines.push(`### ${t("workspace.handoff.extractedSignatures")}\n\`\`\`\n${snapshot.extractedApisAndContracts.join("\n")}\n\`\`\``);
  }
  if (snapshot.planContracts.length === 0 && snapshot.extractedApisAndContracts.length === 0) {
    apiLines.push(t("workspace.handoff.noContractsRecorded"));
  }
  sections.push(apiLines.join("\n\n"));

  // 3. Completed Work & File Changes
  const workLines: string[] = [`## 3. ${t("workspace.handoff.secChanges")}`];
  if (snapshot.fileChanges.length > 0) {
    for (const f of snapshot.fileChanges) {
      workLines.push(`- \`${f.path}\` (${f.change}, +${f.additions}/-${f.deletions})`);
      if (f.diffExcerpt) {
        workLines.push(`\`\`\`diff\n${f.diffExcerpt}\n\`\`\``);
      }
    }
  } else {
    workLines.push(t("workspace.handoff.noFilesRecorded"));
  }
  if (snapshot.recentTools.length > 0) {
    workLines.push(`### ${t("workspace.handoff.recentTools")}`);
    for (const tool of snapshot.recentTools) {
      const status = tool.ok === true ? "OK" : tool.ok === false ? "FAILED" : "RUN";
      workLines.push(`- [${status}] \`${tool.tool}\`: ${tool.title}`);
    }
  }
  sections.push(workLines.join("\n"));

  // 4. Recent Assistant Outputs & Pending Errors
  const stateLines: string[] = [`## 4. ${t("workspace.handoff.secState")}`];
  if (snapshot.pendingErrors.length > 0) {
    stateLines.push(`### ${t("workspace.handoff.pendingErrors")}`);
    for (const err of snapshot.pendingErrors) {
      stateLines.push(`- ${err}`);
    }
  }
  if (snapshot.recentAssistantOutputs.length > 0) {
    stateLines.push(`### ${t("workspace.handoff.recentConclusions")}`);
    for (const out of snapshot.recentAssistantOutputs.slice(-2)) {
      stateLines.push(out);
    }
  } else {
    stateLines.push(t("workspace.handoff.noRecentOutput"));
  }
  sections.push(stateLines.join("\n\n"));

  // 5. Next Steps
  sections.push(
    `## 5. ${t("workspace.handoff.secNextSteps")}\n${t("workspace.handoff.localNextStepsHint")}`,
  );

  return sections.join("\n\n");
}

/**
 * Formats the handoff document as a fresh-window prefix for the incoming model.
 */
export function buildHandoffCarrierPrefix(
  document: string,
  source: "model" | "tokage_local",
  fromModelName?: string,
): string {
  const provenance =
    source === "tokage_local"
      ? "Extracted locally by Tokage from session history, diffs, and contracts"
      : `Generated by outgoing model (${fromModelName || "previous model"}) and verified with Tokage session artifacts`;
  return [
    "# [TOKAGE SESSION HANDOFF DOCUMENT]",
    `Provenance: ${provenance}`,
    "You are taking over an active coding session in a fresh context window. Review the handoff document below (including goals, key contracts, APIs, completed file changes, and current status) and continue seamlessly without redoing completed work.",
    "",
    document.trim(),
  ].join("\n");
}
